const TGIconPath *TGIconPathNamed(const char *name) {
	if (!name)
		return NULL;
	for (size_t i = 0; i < sizeof(kPaths) / sizeof(kPaths[0]); i++)
		if (strcmp(kPaths[i].name, name) == 0)
			return &kPaths[i];
	return NULL;
}

size_t TGIconPathCount(void) {
	return sizeof(kPaths) / sizeof(kPaths[0]);
}

const TGIconPath *TGIconPathAt(size_t index) {
	return index < TGIconPathCount() ? &kPaths[index] : NULL;
}
